"""Immutable FIB versions, canonical forwarding runs and forwarding changes.

All addresses are full unsigned 128-bit integers; U = 2**128 is the exclusive
upper domain bound and is never a run start.
"""
import heapq
from bisect import bisect_right

U = 1 << 128
